) AS (
  VALUES 
    (455::BIGINT, 'Si usted quiere aprender sobre el curso, matricule con él, además que casi siempre el Gerente y Coordinadores de Proyecto salen del grupo de él, entonces si le interesa estar muy metido en el proyecto, él es la mejor opción.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '65eeb431677f33aef32520574098aa7b13b5f6e5d73c48781abc5e3a97784d07'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Explica demasiado bien, le recomiendo que vaya con la materia al dia porque ve la participacion en clase, aclara las dudas, se preocupa por el estudiante. Vaya a hora consulta, toma en cuenta esa asistencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ab0bf3b1707df33af36d0bde981e00d86a42e665ad03f622be967613defeac14'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Si escogen el "proyecto grande" sus exámenes son calificados por sus compañeros, diferencias con ellos se ven reflejadas en su nota. Si es de Ing. Física no matricule con este profesor, ese proyecto requiere tiempo para bingos, ventas y reuniones. Tiempo que usted no tiene en décimo semestre.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'f811779a2d7f4bc90b63cfe34746f7f908e674b3069a78858ff18eda6425c5a8'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'No recomiendo llevar el curso con este profe si son de Ing. Física. Todo el semestre se notó un claro favoritismo para los que sí eran de produ. Él se desliga de revisar, hace 3 tareas y 2 quices sin avisar. Los “exámenes” son coevaluaciones entres los estudiantes. Mejor lleven con el otro profe.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '47976b4ef2d102be33ece3e900a9ff6396969c411ff9481272706b326172962c'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Si son de Ingeniería Física, NO MATRICULEN CON ÉL. Ese profe odia a la gente de Ingeniería Física y los humilla por no saber cosas de produ. Si hacen “proyecto grande”, los exámenes es una coevaluación entre los estudiantes y no se aprende nada. Solo hace 2 quices sin avisar en todo el semestre.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-10T00:00:00+00:00'::TIMESTAMPTZ, '911ad4e489f0603cdd1ba244efc3784c45ac02b1ed13bae9e42a1324bcc6752f'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'No es el mejor profe del TEC, pero no está mal, los exámenes son cortos y sencillos, califica suave. Dele sin miedo PD: Tenga clara la materia de costos I, le va a facilitar mucho costos II'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e383f6400a32b70b1ed9d2f2be050229dc5a66230511a6487a885f5b0ce093fa'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Consiga un buen grupo de trabajo y aprenda a tomar apuntes ya que él no usa presentaciones y no sube casi nada al tec digital. Los exámenes son medio rudos así que póngale desde el inicio. Vaya a consulta. No va a saber de sus notas hasta el puro final, es suave en evaluar el proyecto.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'cc16a528c0c823fe0f57808d9a405a58ed1ceda87f4bfab6440ff3ff22279e4f'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Evite llevar con él si puede, pero si no le queda de otra: a-) La clave es formar un buen equipo de trabajo para el proyecto y las tareas (lo van a salvar con la nota). b-) Pase tomando apuntes de todo, el profe nunca sube las presentaciones. c-) Vaya a hora consulta, el profe lo considera mucho.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1f517c090dcc301b1a621314d20e0c1cec4146576dc0c0f272f4336388dc59ec'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Estudie las presentaciones del profe y va a pasar sin problema. Haga todos los quices como si fuera el último ya que con estos es con lo que se pasa el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4a75ec8e52fc2bc296c37d658c007ff8e30d005bd2126073d90e05b6bbfa0bf5'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'De los 2 profes me quedo con el, el curso es mas llevadero que con Diogenes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '42464a8cbbc7476a37a3f55b580ed8cfbe17602e7ddafce2145fdf684c34a99b'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Lleve costos 2 con él y no es para nada como lo pintan los comentarios anteriores. Haga todo como se lo piden y va a pasar sin problemas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e8882425ff161826e6b22c9e9f8490e47f7d97e980546a8904f010f84c735b5e'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'El curso es una experiencia muy bonita por el proyecto que se realiza, pero el profe como tal con la materia es bastante malo, muy aburrido, solo leyendo presentaciones, deja como 4 tareas en grupos, hace los quiz en clase a mano y son sorpresa. El método de los examenes es poco didáctico.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7a72dba08d3f7f8d749069429fa2e2bfd15ed9efa1a8a8afbd1260c5b803d3b4'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Es una mierda de profesor y aún peor ser humano, lo peor que me he encontrado de todos los profesores que he tenido en el tec, y no es poco decir.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'f37dfde3a4dc58fa7a88c179a6abe4f6889caec089a926ea44a9764e2198edae'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Yo leí los comentarios de aquí y me asusté, no sé si fue que cambió, pero fue muy buen profesor, explicaba bien la materia, las retroalimentaciones eran con mucho respeto y tranquilo y siempre estaba para atender dudas. Pero si hay que estar atento porque le gusta la participación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '6ed4608e3c55f687aeda1b1ea4248f82c89a7243d3570d32f8f3f990b29c9317'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Es demasiado prepotente, es muy odioso para responder, hace las clases muy aburridas y habla muy lento, pésimo profe'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, '566133be335c142451b09ade9db70658928f34e36da17f3792da13253af07629'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es un prepotente, dice "hagan preguntas", pero se nota que odia que le pregunten, es muy odioso para responder, se traba mucho cuando habla y enreda, hace ejemplos interminables, se distrae y por eso me perdía mucho en clase, hace las clases muy aburridas y habla muy lento'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'ebff190fa42a907d7d2192e2f695d13577e456bdf22b18ac1b62138434505b2d'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Demasiado grosero y prepotente'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '85affbcacd1a662020d449e5ebcf92eed125410626e3049be607d1aa973e936c'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'El mae es intenso y llama a que participen si no sabe la respuesta se queda esperando hasta que hable y humilla bastante al estudiante cuando no sabe. Califica duro los proyectos pero si le pone pasa, los quizzes no se puede devolver y valen mucho.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '311844aa88845348e553986a2c62cdc181d3b4d09179e781486acc672830ec2a'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Es una completa basura como profesor y sospecho que como persona lo es aun mas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'cb2aacbcda40e0e48378a0d5b573507e8acb6b89e9927ffa9cebcc800e9819e7'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Es aburrido, es malhumorado, califica duro los proyectos pero se pasa si uno le pone, los quices son fuertes porque no te permiten devolverte.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '3d433b5938f1e837c2cdaabbe36b0d37e09e90d88a6391cdcce3aea2ee5f0fe7'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'El profe es medio aburrido, pero en clase intenta dejar todo claro, el material de apoyo es bastante claro. En los proyectos califica duro. Se pasa, pero muérdase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3a9a611e7c59bb0303572c402ef21cda135ce8ef2b2faa5b38da3adb326fdcb2'::TEXT, ARRAY[1722]::BIGINT[]),
    (455::BIGINT, 'Usualmente no pregunta directamente, es grosero al responder lo que hace que la gente no participe, eso lo molesta también. Quices binarios, con respuestas malas, hay que reclamarle bastante para que de los puntos. La materia es linda pero el profe no siempre lo explica de la mejor manera'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '97ca6164331b7cd272d1379700b28ba4129ae919e20899b71721dacbd4ee138d'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Explica bastante bien y las presentaciones son claras. Responde mala gente cuando uno le pregunta, y muchas veces no aclara, pero igual es importante participar. El principal problema fue que cometió errores en todas las evaluaciones! En todo le reclamamos. Eso hizo peor el curso. Califica tardísimo'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '558b3e71dc6aaa362d5f00c045c208b2b67a05927a6830c0fab8ad29852b447f'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'No meta Análisis con este profe. Como profe es muy malo y como persona también queda mucho debiendo. La mitad de la clase se queda.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'e1dcf9afb55931b72a1cd039e514b6d609e0e84028e894a5cce8c8ff1cb432f7'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'cd14a560d909fb2a04c8fdcaf75c976dd1c8cd6549c714582e03a842441d57db'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'El profesor se cree mucho, y a la mayoría de preguntas no les da una respuesta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '67da328e0ae0b3aa76f2f86b34766bcec3fb4a0ea01272a9b381e30b8a841ad0'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, '1-Presencial: acá no pasa presentaciones y hay que apuntar todo. Es más duro, pero mejor que Diógenes. 2-Virtual: el curso virtual se hace más llevadero, se gana con un esfuerzo regular y sí pasa ppt''s. Hay que tener cuidado, porque se pone medio sarcástico cuando hace preguntas o se las hacen.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '69c07abd90d5e5ef1f38f58a1fdf224adcc882c8ac4b94dc371f448e356d9990'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'El profe es súper sarcástico, lo llevé en virtual y fue súper fácil, más que en presencial, porque en presencial no pasaba presentaciones y explica rápido, entonces es mejor llevarlo en virtual, si tiene la oportunidad de llevarlo en virtual es la mejor opción, sino piénselo 2 veces'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'af8c3a797e17a414b49768605412f83a0067fee697cf84f2c93cecb990f37279'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Un irrespetuoso el 90% de las veces jajajaja da miedo preguntarle varas porque lo ridiculiza y le contesta con otra pregunta. Yo si sentí que explicó claro y por ser "tiempos de covid" el mae sí pasó presentaciones. pero si es presencial, mucha suerte porque qué martirio'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '37b2f5ad96917e392efcb1e0bc640db2ee80b76c8db739bebc2b29f99a7b7acf'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es un profesor muy vago, en este curso él no hace absolutamente nada. Las clases no son provechosas, el proyecto sale a como sea, él nunca nos enseña como aplicar la teoría en dicho proyecto'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'a566ca0d65b607de163a2de74d79d08835332a3f411248a841cd4bd40631a518'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'En todas las clases explica la materia con claridad y deja tareas con la misma dificultad al examen. Sin embargo, cuando un estudiante tiene dudas a veces explica de una forma sarcástica. En consulta le explica a uno con claridad pero sin antes regañarlo un poco dependiendo de las preguntas tenga.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '31068ba8687e5f873e2e2c50a7142dc316fa0233092ce7921b7a88906121937d'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es un vago, no explica, solo chistes malos y gasta horas hablando mal de todo el mundo. Como es profesor? No lo se, pero hay muchos así'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'c5c9d800ab0707b409538ea364f4b965d7170d1c727a18903f009880dc71079a'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Me dijeron el curso era malo pero se quedaron cortos. No hemos aprendido nada, y ha dedicado el semestre a decirnos somos unos estupidos'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-10-06T00:00:00+00:00'::TIMESTAMPTZ, 'd42282f7949e841f8ec86663746489f73baf72298bcb83cba424de30d828dddb'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Asco de profesor que se burla de los estudiantes y es profesor con los que preguntan. Además, el curso quita demasiado tiempo, ya que implica mucha participación en la mayoría de actividades que se organizan, y que no se aprende mucho con él. Les recomiendo matricularlo con Jary'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-28T00:00:00+00:00'::TIMESTAMPTZ, '2f8dc71f4661890e01bffe489b691815380925ab4fc679f57dabda91be47ab73'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Un curso de 3 créditos pero debería valer 5 por lo menos con este profesor, se burla de los estudiantes, chistes malos y si no hace el proyecto de grupo se lo come, el curso en si es fácil pero una breteada enorme y tampoco es que se gane o más importante se aprenda mucho.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-02T00:00:00+00:00'::TIMESTAMPTZ, '717b05cd2d0022b38920076a4f37425adb189efbbb3286727b6bcdf69a3471aa'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'El curso en si es difícil, el si q no lo facilita tampoco, no es una clase que se desee ir, trata de ser amistoso pero si raya lo sarcástico y nunca pierde. La mitad se queda, para no ser de esa mitad póngale mucho, no se agueve por el primer exámen y los quices, quedese hasta el final.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9c6e0651d3cebc03028a4d23bc2db9329566b1f5748095a137c87872298a49be'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Si se compara con Análisis económico en este curso él es la otra cara de la moneda (en cuanto a dificultad para aprobar), aunque suele conservar su tono burlesco, y trato sarcástico con sus estudiantes. No lo recomiendo ni para chofer.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '858c20299705c581394b059381369753a73a612d2d22c91e338ab1acf1b32919'::TEXT, ARRAY[1776]::BIGINT[]),
    (455::BIGINT, 'Es una persona que sabe. Es un problema que piense todos los demas profesores son malos y solo el sobresale. Me toco ver lo mal que habla de otros profesores buenos como Jary Brenes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa']::TEXT[], '2017-09-08T00:00:00+00:00'::TIMESTAMPTZ, '413ba3dc1c66591984000d864e27ce7f9d6a1e2afd266f38fb6f59ff29f6c781'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'La verdad es no tenerle miedo. El curso en sí es duro, pero nada más ponerle bastante. En consulta ayuda bastante. Hay que aguantarle hasta el final (si lo hace, pasa). El proyecto lo revisa relativamente suave.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6673f740ded4cc103296f8591da1c608fb79a1f57016f2f684027c5d14c6483a'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es muy sarcástico y no ayuda en consulta pero explica claro..compren vaselina..'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-05-21T00:00:00+00:00'::TIMESTAMPTZ, '0434a4424eaec5031c3db46af6b0bb863402a142b6925e38cc024c8a25683e04'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Se nota que sabe mucho acerca de la materia. Lo malo es que no genera un clima de confianza en la clase, para que el estudiante se sienta cómodo preguntando.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-03-31T00:00:00+00:00'::TIMESTAMPTZ, 'b731c2e446ec0604aeca5b37ca7a2fda62759da2940e894e5e5bba981160cfd8'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Pésimos, hace los ejercicios más básicos y no se compara con los del examen o tareas. No le gusta responder a las dudas en clases. No lo recomiendo!!'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '097e0f84ebc6bfd84ff6f7ada421df8ad6becd348d313ae37dfc0ed57aa43459'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Muy buen profesor pero al preguntarle algo en clase parece burlarse de algunos estudiantes. Es mejor ir a consulta. El primer examen es el más difícil, ya que con el segundo la mayoría salen bien y el proyecto no lo califica tan duro. Lo recomiendo si quiere ponerle y aprende Contar hasta 3 = Quiz'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '723bcfe5ccc2dbb6835891453a5ccde5a6f7a82e559cab8b519e85d50677c347'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'no explica bien en clase ni en consulta, los exámenes son difíciles, los quices son sin previo aviso. Puede tener mucho conocimiento y saber mucho sobre evaluación económica y otros temas, pero no es un buen profesor. Debería de mejorar su conducta con los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'a695ccb6008f1387a59f1c5aca3aa79c8da54c196e2a7d1b1acfb24716262f11'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es un profesor duro, definitivamente uno aprende mucho con él, pero hay que ponerle bastante. Si, se quedo medio grupo, pero porque medio grupo se fue, si llega al final verá que el segundo examen no es tan duro y el proyecto es normal, es muy rudo en el primer examen.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '45dfede620d4759eed1a6edeaf89b8dc778970b409b8d9a0d1546edb7fc99d9a'::TEXT, ARRAY[1763]::BIGINT[]),
    (455::BIGINT, 'Es simplemente un cp como persona, como profesor y como todo. Se quedó más de la mitad'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1d50be540bb24caed2cef4728238a2db9791c5b1e92387350258fd534e2c45c1'::TEXT, ARRAY[1763]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
